  const r = cli(file, 'add', 'netflix', '9.99');
  assert.equal(r.code, 1);
  assert.match(r.err, /already on the list/);
}));

test('add and list weekly plans', () => withFile((file) => {
  assert.equal(cli(file, 'add', 'Meal kit', '59.90', '--every', 'week', '--since', '2026-10-20').code, 0);
  assert.equal(cli(file, 'add', 'Gym', '15', '--every', 'weekly', '--since', '2026-10-24').code, 0);
  const list = cli(file, 'list');
  assert.equal(list.code, 0);
  assert.match(list.out, /Meal kit\s+€59\.90 weekly\s+€259\.57 a month/);
  assert.match(list.out, /Gym\s+€15\.00 weekly\s+€65\.00 a month/);
}));

test('weekly plans in total', () => withFile((file) => {
  cli(file, 'add', 'Netflix', '12.99', '--since', '2026-10-01');
  cli(file, 'add', 'Meal kit', '59.90', '--every', 'week', '--since', '2026-10-01');
  const total = cli(file, 'total');
  assert.equal(total.code, 0);
  assert.equal(total.out, 'Monthly total: €272.55 (2 plans)\n');
}));

test('weekly plans in renewals', () => withFile((file) => {
  cli(file, 'add', 'Meal kit', '59.90', '--every', 'week', '--since', '2026-10-20');
  const r = cli(file, 'renewals', '--within', '7', '--today', '2026-10-24');
  assert.equal(r.code, 0);
  assert.equal(r.out, '27 Oct  Meal kit  €59.90\n');
}));

